(function() {
  'use strict';

  // 教学假设 - 明确说明这些是示例值，非真实训练权重
  const TEACHING_ASSUMPTIONS = [
    "本演示使用简化的教学示例数据，非论文中的真实训练权重",
    "假设信道稀疏性成立（路径数 L 远小于候选数）",
    "假设噪声在残差更新过程中被有效抑制",
    "自适应步骤在每次迭代中均执行（除非特别说明）"
  ];

  // 局限性说明
  const LIMITATIONS = [
    "实际实现需考虑时钟同步误差对 ToA 估计的影响",
    "模型仅考虑单反射 NLoS 路径，忽略多反射场景",
    "演示未展示完整的 K 次自适应迭代过程，仅展示单次主迭代",
    "真实系统中需处理矩阵维度爆炸问题，此处已简化"
  ];

  // 算法步骤数据
  const STEPS = [
    {
      title: "步骤 1：初始化残差",
      desc: "对于第一条路径 (l=1)，将残差 R1 设置为接收信号 y。",
      sources: ["S136", "S196"],
      data: { l: 1, energy: 1.000, index: "-", angle: "-", matrix: "初始 ω(0)" }
    },
    {
      title: "步骤 2：寻找最大相关索引",
      desc: "遍历所有候选列 m，计算 corr = |ω_m^H * Rl|，记录产生最大 corr 的索引 h̃l。",
      sources: ["S135", "S196"],
      data: { l: 1, energy: 1.000, index: "42", angle: "-", matrix: "初始 ω(0)" }
    },
    {
      title: "步骤 3：执行自适应搜索",
      desc: "利用当前索引 h̃l 调用自适应搜索子程序，更新下一轮迭代的角度候选集和感知矩阵 ω(k)。",
      sources: ["S191", "S228"],
      data: { l: 1, energy: 1.000, index: "42", angle: "1.35 rad", matrix: "更新 ω(1)" }
    },
    {
      title: "步骤 4：更新残差与 ToA",
      desc: "计算系数 βl，更新残差 Rl+1 = Rl - βl * ω，并根据距离公式计算 τl。",
      sources: ["S139", "S140", "S228"],
      data: { l: 2, energy: 0.350, index: "42", angle: "1.35 rad", matrix: "更新 ω(1)" }
    }
  ];

  let currentStep = 0;
  const canvas = document.getElementById('chap-5-algo-canvas');
  const ctx = canvas.getContext('2d');
  const overlay = document.getElementById('chap-5-algo-overlay');
  const stepNumEl = document.getElementById('chap-5-algo-step-num');
  const stepTitleEl = document.getElementById('chap-5-algo-step-title');
  const stepDescEl = document.getElementById('chap-5-algo-step-desc');
  const btnNext = document.getElementById('chap-5-algo-btn-next');
  const btnPrev = document.getElementById('chap-5-algo-btn-prev');
  const btnReset = document.getElementById('chap-5-algo-btn-reset');

  // 数据面板元素
  const valL = document.getElementById('chap-5-algo-val-l');
  const valEnergy = document.getElementById('chap-5-algo-val-energy');
  const valIndex = document.getElementById('chap-5-algo-val-index');
  const valAngle = document.getElementById('chap-5-algo-val-angle');
  const valMatrix = document.getElementById('chap-5-algo-val-matrix');

  // 绘制画布内容
  function drawCanvas(step) {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 背景
    ctx.fillStyle = '#F5F5F7';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // 绘制信号路径
    ctx.strokeStyle = '#2C3E50';
    ctx.lineWidth = 2;

    // 绘制多条路径示意
    const paths = [
      { x1: 50, y1: 200, x2: 550, y2: 100, alpha: step >= 3 ? 0.3 : 1.0 },
      { x1: 50, y1: 200, x2: 550, y2: 200, alpha: step >= 3 ? 0.3 : 1.0 },
      { x1: 50, y1: 200, x2: 550, y2: 300, alpha: step >= 3 ? 0.3 : 1.0 }
    ];

    paths.forEach(path => {
      ctx.globalAlpha = path.alpha;
      ctx.beginPath();
      ctx.moveTo(path.x1, path.y1);
      ctx.lineTo(path.x2, path.y2);
      ctx.stroke();

      // 绘制端点
      ctx.fillStyle = '#00B894';
      ctx.beginPath();
      ctx.arc(path.x2, path.y2, 6, 0, Math.PI * 2);
      ctx.fill();
    });

    ctx.globalAlpha = 1.0;

    // 绘制当前高亮路径
    if (step >= 1) {
      ctx.strokeStyle = '#E17055';
      ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.moveTo(50, 200);
      ctx.lineTo(550, 200);
      ctx.stroke();

      // 绘制高亮端点
      ctx.fillStyle = '#E17055';
      ctx.beginPath();
      ctx.arc(550, 200, 10, 0, Math.PI * 2);
      ctx.fill();

      // 绘制相关性计算示意
      if (step === 1) {
        ctx.fillStyle = 'rgba(0, 184, 148, 0.2)';
        ctx.fillRect(300, 150, 200, 100);
        ctx.strokeStyle = '#00B894';
        ctx.strokeRect(300, 150, 200, 100);

        ctx.fillStyle = '#2C3E50';
        ctx.font = '14px system-ui';
        ctx.textAlign = 'center';
        ctx.fillText('相关性计算', 400, 200);
      }

      // 绘制自适应搜索区域
      if (step === 2) {
        ctx.fillStyle = 'rgba(0, 184, 148, 0.15)';
        ctx.beginPath();
        ctx.arc(550, 200, 60, 0, Math.PI * 2);
        ctx.fill();
        ctx.strokeStyle = '#00B894';
        ctx.stroke();

        ctx.fillStyle = '#2C3E50';
        ctx.font = '14px system-ui';
        ctx.textAlign = 'center';
        ctx.fillText('自适应搜索区域', 550, 130);
      }

      // 绘制残差更新示意
      if (step === 3) {
        ctx.fillStyle = 'rgba(225, 112, 85, 0.2)';
        ctx.fillRect(50, 180, 500, 40);
        ctx.strokeStyle = '#E17055';
        ctx.strokeRect(50, 180, 500, 40);

        ctx.fillStyle = '#2C3E50';
        ctx.font = '14px system-ui';
        ctx.textAlign = 'center';
        ctx.fillText('残差更新：R₂ = R₁ - β₁ω', 300, 205);
      }
    }

    // 绘制标签
    ctx.fillStyle = '#2C3E50';
    ctx.font = '16px system-ui';
    ctx.textAlign = 'left';
    ctx.fillText('发射端', 20, 205);
    ctx.textAlign = 'right';
    ctx.fillText('接收端', 580, 205);
  }

  // 更新界面
  function updateUI() {
    const step = STEPS[currentStep];

    // 更新叠加层
    stepNumEl.textContent = currentStep + 1;
    stepTitleEl.textContent = step.title;
    stepDescEl.textContent = step.desc;

    // 更新数据面板
    valL.textContent = step.data.l;
    valEnergy.textContent = step.data.energy.toFixed(3);
    valIndex.textContent = step.data.index;
    valAngle.textContent = step.data.angle;
    valMatrix.textContent = step.data.matrix;

    // 更新按钮状态
    btnPrev.disabled = currentStep === 0;
    btnNext.disabled = currentStep === STEPS.length - 1;

    // 绘制画布
    drawCanvas(currentStep);

    // 显示叠加层
    overlay.classList.add('active');
  }

  // 事件处理
  function handleNext() {
    if (currentStep < STEPS.length - 1) {
      currentStep++;
      updateUI();
    }
  }

  function handlePrev() {
    if (currentStep > 0) {
      currentStep--;
      updateUI();
    }
  }

  function handleReset() {
    currentStep = 0;
    updateUI();
  }

  // 键盘导航
  function handleKeydown(e) {
    if (e.key === 'ArrowRight' || e.key === ' ') {
      e.preventDefault();
      handleNext();
    } else if (e.key === 'ArrowLeft') {
      e.preventDefault();
      handlePrev();
    } else if (e.key === 'r' || e.key === 'R') {
      handleReset();
    }
  }

  // 来源按钮处理
  function handleSourceClick(e) {
    const sourceId = e.target.getAttribute('data-source');
    if (sourceId && window.paperMindData && window.paperMindData.sources) {
      // 由宿主内核处理来源跳转
      console.log('Source requested:', sourceId);
    }
  }

  // 初始化
  function init() {
    // 绑定事件
    btnNext.addEventListener('click', handleNext);
    btnPrev.addEventListener('click', handlePrev);
    btnReset.addEventListener('click', handleReset);
    document.addEventListener('keydown', handleKeydown);

    // 绑定来源按钮
    document.querySelectorAll('.source-btn').forEach(btn => {
      btn.addEventListener('click', handleSourceClick);
    });

    // 初始绘制
    drawCanvas(0);
    updateUI();
  }

  // 启动
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
